<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php';
if(is_logged_in()) redirect('account.php');
$errors=[];$name='';$email='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$password=$_POST['password']??'';$confirm=$_POST['confirm']??'';
if(strlen($name)<2)$errors[]='Emri duhet të ketë së paku 2 karaktere.';if(!filter_var($email,FILTER_VALIDATE_EMAIL))$errors[]='Shkruani një email valid.';if(strlen($password)<6)$errors[]='Fjalëkalimi duhet të ketë së paku 6 karaktere.';if($password!==$confirm)$errors[]='Fjalëkalimet nuk përputhen.';
if(!$errors){$check=$db->prepare('SELECT id FROM users WHERE email=?');$check->bind_param('s',$email);$check->execute();if($check->get_result()->num_rows)$errors[]='Ky email është i regjistruar.';else{$hash=password_hash($password,PASSWORD_DEFAULT);$stmt=$db->prepare("INSERT INTO users(name,email,password,role) VALUES(?,?,?,'customer')");$stmt->bind_param('sss',$name,$email,$hash);$stmt->execute();$_SESSION['user']=['id'=>$db->insert_id,'name'=>$name,'email'=>$email,'role'=>'customer'];flash('success','Mirë se erdhe në Nexa Store!');redirect('account.php');}}}
$pageTitle='Krijo llogari'; require __DIR__.'/includes/header.php';
?>
<section class="auth-section"><div class="container"><form class="auth-card" method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><p class="eyebrow">Bëhu pjesë e Nexa</p><h1>Krijo llogari</h1><p class="muted">Ruaj porositë dhe blej më shpejt.</p><?php if($errors): ?><div class="error-list"><?php foreach($errors as $error): ?><div>• <?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><div class="form-group"><label>Emri i plotë</label><input name="name" value="<?= e($name) ?>" required></div><div class="form-group"><label>Email</label><input type="email" name="email" value="<?= e($email) ?>" required></div><div class="form-group"><label>Fjalëkalimi</label><input type="password" name="password" required></div><div class="form-group"><label>Konfirmo fjalëkalimin</label><input type="password" name="confirm" required></div><button class="button button-dark" style="width:100%">Regjistrohu</button><p class="muted" style="text-align:center">Ke llogari? <a class="text-link" href="login.php">Hyr këtu</a></p></form></div></section>
